WITH cleaned AS (SELECT id, customer_id, device, country, TRIM(device) AS clean_device, LENGTH(browser) AS browser_length FROM sessions WHERE started_at > DATE '2023-04-23' AND country IS NOT NULL) SELECT * FROM (SELECT country, device, browser_length FROM cleaned) src PIVOT (MAX(browser_length) AS total, COUNT(1) AS item_count FOR device IN ('desktop' AS desktop, 'tablet' AS tablet));
